(()=>{async function u(t){n.innerHTML='<div class="col-12 text-center py-5"><div class="spinner-border text-primary" role="status"><span class="visually-hidden">Загрузка...<\/span><\/div><\/div>';try{const i=await fetch("/Catalog/Search?query="+encodeURIComponent(t));if(!i.ok)throw new Error("HTTP "+i.status);const r=await i.text();n.innerHTML=r.trim()?r:'<div class="col-12"><div class="alert alert-info">Ничего не найдено<\/div><\/div>'}catch(i){n.innerHTML='<div class="col-12"><div class="alert alert-danger">Ошибка поиска<\/div><\/div>';console.error(i)}}const t=document.getElementById("searchInput"),n=document.getElementById("catalogGrid");if(t&&n){const r=n.innerHTML;let i;t.addEventListener("input",()=>{clearTimeout(i);const f=t.value.trim();if(f.length<2){n.innerHTML=r;return}i=setTimeout(()=>u(f),300)})}})();